grid = np.array([list(map(int, line.split())) for line in grid_str.strip().split('\n')])

# Look for all sequences of 3 consecutive values (0,1,2 or increasing)
# in columns or rows

# Check vertical sequences in each column
print("Looking for special triplets in vertical sequences:")
for c in range(21):
    col = grid[:, c]
    # Look for patterns of 3 non-1 values in a column
    consecutive_non_1 = []
    for r in range(22):
        if col[r] != 1:
            consecutive_non_1.append((r, col[r]))
        else:
            if len(consecutive_non_1) >= 3:
                print(f"Col {c}: {consecutive_non_1[-3:]}")
            consecutive_non_1 = []

# Check horizontal sequences in each row
print("\nLooking for special triplets in horizontal sequences:")
for r in range(22):
    row = grid[r, :]
    consecutive_non_1 = []
    for c in range(21):
        if row[c] != 1:
            consecutive_non_1.append((c, row[c]))
        else:
            if len(consecutive_non_1) >= 3:
                print(f"Row {r}: {consecutive_non_1[-3:]}")
            consecutive_non_1 = []

# Let me look for different types of patterns
print("\n\nLets find if there's symmetry or a recurring pattern:")
# Count how many of each non-1 value
from collections import Counter
non_1_vals = Counter()
for r in range(22):
    for c in range(21):
        if grid[r, c] != 1:
            non_1_vals[grid[r, c]] += 1

print(f"Count of each non-1 value: {non_1_vals}")

